192	basic_string<libzippp_uint8> ZipEntry::readAsBinaryString(ZipArchive::State state, libzippp_uint64 size) const {
193	    if (isNull()) { return basic_string<libzippp_uint8>(); }
194	    if (session.expired()) { return basic_string<libzippp_uint8>(); }
195	    libzippp_uint8* content = (libzippp_uint8*)zipFile->readEntry(*this, true, state, size);
196	    if (content==nullptr) { return basic_string<libzippp_uint8>(); } //happen if the ZipArchive has been closed or the entry does not exist in the state
197	
198	    //see readAsText: the length must reflect the requested state (zero bytes inside the
199	    //content are preserved, the extra '\0' is only an allocation artifact)
200	    libzippp_uint64 maxSize = zipFile->getEntry((libzippp_int64)index, state).getSize();
201	    libzippp_uint64 length = size==0 || size>maxSize ? maxSize : size;
202	    basic_string<libzippp_uint8> str(content, length);
203	    delete[] content;
204	    return str;
205	}
