207	int ZipEntry::readContent(std::ostream& ofOutput, ZipArchive::State state, libzippp_uint64 chunksize) const {
208	   //an invalid stream is reported first, as for a valid entry; the error codes below
209	   //are the ones guaranteed when the stream itself is valid
210	   if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
211	   //a null entry is invalid; a non-null entry whose opening ended is reported as coming
212	   //from a no-longer-open archive. The archive object itself may have been destroyed,
213	   //hence these checks must not dereference zipFile.
214	   if (isNull()) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
215	   if (session.expired()) { return LIBZIPPP_ERROR_NOT_OPEN; }
216	   return zipFile->readEntry(*this, ofOutput, state, chunksize);
217	}
