252	bool ZipArchive::isEntryUsable(const ZipEntry& entry) const {
253	    if (entry.isNull()) { return false; }
254	    if (entry.zipFile!=this) { return false; }
255	    //the entry must belong to the CURRENT opening of this archive: its session marker
256	    //is the one this archive holds right now
257	    std::shared_ptr<ZipEntrySession> entryOpening = entry.session.lock();
258	    return entryOpening && entryOpening==entrySession;
259	}
