314	bool ZipArchive::openBuffer(void** data, libzippp_uint32 size, OpenMode om, bool checkConsistency) {
315	    zip_error_t error;
316	    zip_error_init(&error);
317	
318	    /* create source from buffer */
319	    zip_source* localZipSource = zip_source_buffer_create(*data, size, 0, &error);
320	    if (localZipSource == nullptr) {
321	        Helper::callErrorHandlingCallback(&error, "can't create zip source: %s\n", errorHandlingCallback);
322	        zip_error_fini(&error);
323	        return false;
324	    }
325	
326	    bool open = openSource(localZipSource, om, checkConsistency);
327	    if (open) {
328	        if (om==Write || om==New) {
329	            bufferData = data;
330	            bufferLength = size;
331	
332	            //prevents libzip to delete the source when closing the ZipArchive
333	            zip_source_keep(localZipSource);
334	        }
335	    } else {
336	        zip_source_free(localZipSource);
337	        localZipSource = nullptr;
338	    }
339	    return open;
340	}
