342	bool ZipArchive::openSource(zip_source* source, OpenMode om, bool checkConsistency) {
343	    int zipFlag = 0;
344	    if (om == ReadOnly) { zipFlag = 0; }
345	    else if (om == Write) { zipFlag = ZIP_CREATE; }
346	    else if (om == New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
347	    else { return false; }
348	    if (checkConsistency) {
349	        zipFlag = zipFlag | ZIP_CHECKCONS;
350	    }
351	
352	    zip_error_t error;
353	    zip_error_init(&error);
354	
355	    /* open zip archive from source */
356	    zipHandle = zip_open_from_source(source, zipFlag, &error);
357	    if (zipHandle == nullptr) {
358	        Helper::callErrorHandlingCallback(&error, "can't open zip from source: %s\n", errorHandlingCallback);
359	        zip_error_fini(&error);
360	        return false;
361	    }
362	    zip_error_fini(&error);
363	
364	    zipSource = source;
365	
366	#ifdef LIBZIPPP_WITH_ENCRYPTION
367	    if (isEncrypted()) {
368	        int result = zip_set_default_password(zipHandle, password.c_str());
369	        if (result != 0) {
370	            close();
371	            return false;
372	        }
373	    }
374	#endif
375	
376	    mode = om;
377	    beginEntrySession(); //entries created by this opening share this marker
378	    return true;
379	}
