381	bool ZipArchive::open(OpenMode om, bool checkConsistency) {
382	    if (isOpen()) { return om==mode; }
383	
384	    int zipFlag = 0;
385	    if (om==ReadOnly) { zipFlag = 0; }
386	    else if (om==Write) { zipFlag = ZIP_CREATE; }
387	    else if (om==New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
388	    else { return false; }
389	
390	    if (checkConsistency) {
391	        zipFlag = zipFlag | ZIP_CHECKCONS;
392	    }
393	
394	    int errorFlag = 0;
395	    zipHandle = zip_open(path.c_str(), zipFlag, &errorFlag);
396	
397	    //error during opening of the file
398	    if (errorFlag!=ZIP_ER_OK) {
399	        zip_error_t error;
400	        zip_error_init_with_code(&error, errorFlag);
401	        Helper::callErrorHandlingCallback(&error, "unable to open archive: %s\n", errorHandlingCallback);
402	        zip_error_fini(&error);
403	
404	        zipHandle = nullptr;
405	        return false;
406	    }
407	
408	    if (zipHandle!=nullptr) {
409	#ifdef LIBZIPPP_WITH_ENCRYPTION
410	        if (isEncrypted()) {
411	            int result = zip_set_default_password(zipHandle, password.c_str());
412	            if (result!=0) {
413	                close();
414	                return false;
415	            }
416	        }
417	#endif
418	
419	        mode = om;
420	        beginEntrySession(); //entries created by this opening share this marker
421	        return true;
422	    }
423	
424	    return false;
425	}
