427	void progress_callback(zip* /*archive*/, double progression, void* ud) {
428	    ZipArchive* za = static_cast<ZipArchive*>(ud);
429	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
430	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
431	        ZipProgressListener* listener = *it;
432	        listener->progression(progression);
433	    }
434	}
435	
436	int progress_cancel_callback(zip* /*archive*/, void* ud) {
437	    ZipArchive* za = static_cast<ZipArchive*>(ud);
438	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
439	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
440	        ZipProgressListener* listener = *it;
441	        if (listener->cancel())
442	          return 1;
443	    }
444	    return 0;
445	}
