447	int ZipArchive::close(void) {
448	    if (isOpen()) {
449	
450	        //do not handle zipSource at all because it will be deleted by libzip
451	        //directly when not necessary anymore
452	
453	        if (!listeners.empty()) {
454	            zip_register_progress_callback_with_state(zipHandle, progressPrecision, progress_callback, nullptr, this);
455	            zip_register_cancel_callback_with_state(zipHandle, progress_cancel_callback, nullptr, this);
456	        }
457	
458	        //avoid to reset the progress when unzipping
459	        if (mode != ReadOnly) {
460	            progress_callback(zipHandle, 0, this); //enforce the first progression call to be zero
461	        }
462	
463	        int result = zip_close(zipHandle);
464	        if (result!=0) {
465	            //typically a cancelled commit: the archive is still open and usable, the
466	            //session is left untouched so existing entries and their copies remain valid
467	            Helper::callErrorHandlingCallback(zipHandle, "unable to close archive: %s\n", errorHandlingCallback);
468	            return LIBZIPPP_ERROR_HANDLE_FAILURE;
469	        }
470	
471	        zipHandle = nullptr;
472	        //the opening really ended (even if the buffer readback below fails afterwards):
473	        //all entries obtained during it must expire now
474	        endEntrySession();
475	        progress_callback(zipHandle, 1, this); //enforce the last progression call to be one
476	
477	        //push back the changes in the buffer
478	        int res_code = LIBZIPPP_OK;
479	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
480	            int srcOpen = zip_source_open(zipSource);
481	            if (srcOpen==0) {
482	                //IMPORTANT: the rewritten archive is read back into a *freshly allocated*
483	                //buffer. We must never read into nor realloc *bufferData here: that memory
484	                //is the storage backing the libzip source we are currently reading from.
485	                //Reusing it aliases the source and, depending on the libzip version (i.e.
486	                //whether it takes ownership of the buffer when writing), it makes
487	                //zip_source_free() release a buffer that realloc() already moved/freed,
488	                //which results in a double-free (see double_free_report / fromWritableBuffer).
489	                zip_int64_t increment = 1024;
490	                zip_int64_t capacity = bufferLength>0 ? static_cast<zip_int64_t>(bufferLength) : increment;
491	                char* outBuffer = static_cast<char*>(malloc(capacity * sizeof(char)));
492	                char* tempBuffer = outBuffer;
493	                zip_int64_t tempBufferSize = capacity;
494	                zip_int64_t totalRead = 0;
495	                zip_int64_t read = (outBuffer==nullptr) ? -1 : zip_source_read(zipSource, tempBuffer, tempBufferSize);
496	                while(read>0) {
497	                    totalRead += read;
498	                    if (totalRead>=capacity) {
499	                        zip_int64_t newCapacity = capacity + increment;
500	                        char* grownBuffer = static_cast<char*>(realloc(outBuffer, newCapacity * sizeof(char)));
501	                        if (grownBuffer==nullptr) {
502	                            Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: unable to extend buffer\n", errorHandlingCallback);
503	                            ::free(outBuffer);
504	                            outBuffer = nullptr;
505	                            read = -1;
506	                            break;
507	                        }
508	                        outBuffer = grownBuffer;
509	                        capacity = newCapacity;
510	                    }
511	                    tempBuffer = outBuffer+totalRead;
512	                    tempBufferSize = capacity-totalRead;
513	                    read = zip_source_read(zipSource, tempBuffer, tempBufferSize);
514	                }
515	
516	                zip_source_close(zipSource);
517	
518	                if (outBuffer!=nullptr && read>=0) {
519	                    //freeing zipSource first guarantees libzip has released whatever it owns
520	                    //before we touch *bufferData. With freep=0 (see openBuffer) libzip never
521	                    //frees *bufferData itself, so reclaiming it here is safe and leak-free.
522	                    zip_source_free(zipSource);
523	                    zipSource = nullptr;
524	
525	                    ::free(*bufferData);
526	                    *bufferData = outBuffer;
527	                    bufferLength = totalRead;
528	                } else {
529	                    Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
530	                    res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
531	                    if (outBuffer!=nullptr) { ::free(outBuffer); }
532	                    zip_source_free(zipSource);
533	                    zipSource = nullptr;
534	                }
535	            } else {
536	                Helper::callErrorHandlingCallback((zip*)nullptr, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
537	                res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
538	
539	                zip_source_free(zipSource);
540	                zipSource = nullptr;
541	            }
542	        }
543	
544	        mode = NotOpen;
545	        return res_code;
546	    }
547	
548	    return LIBZIPPP_OK;
549	}
