551	void ZipArchive::discard(void) {
552	    if (isOpen()) {
553	        zip_discard(zipHandle);
554	        zipHandle = nullptr;
555	
556	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
557	            zip_source_free(zipSource);
558	            zipSource = nullptr;
559	        }
560	
561	        mode = NotOpen;
562	        endEntrySession(); //discarded opening: all its entries expire
563	    }
564	}
