572	string ZipArchive::getComment(State state) const {
573	    if (!isOpen()) { return string(); }
574	
575	    int flag = 0;
576	    if (state==Original) { flag = flag | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
577	    else { flag = flag | ZIP_FL_ENC_GUESS; }
578	
579	    int length = 0;
580	    const char* comment = zip_get_archive_comment(zipHandle, &length, flag);
