619	    libzippp_uint64 size = stat->size;
620	    libzippp_uint16 compMethod;
621	    if (useArchiveCompressionMethod) {
622	        compMethod = this->compressionMethod;
623	    } else {
624	        compMethod = stat->comp_method;
625	    }
626	    libzippp_uint16 encMethod = stat->encryption_method;
627	    libzippp_uint64 sizeComp = stat->comp_size;
628	    int crc = stat->crc;
