637	
638	ZipEntry ZipArchive::resolveEntry(const ZipEntry& zipEntry, State state, libzippp_uint64* outSize) const {
639	    if (outSize!=nullptr) { *outSize = 0; }
640	
641	    //a null-ZipEntry (e.g. obtained through getEntry in a state where the name does not
642	    //exist) cannot be resolved in any state, nor can an entry coming from another archive
643	    //or from an opening that has ended
644	    if (!isEntryUsable(zipEntry)) { return ZipEntry(); }
645	
646	    int flag = stateFlags(state);
647	    struct zip_stat stat;
648	    zip_stat_init(&stat);
649	
650	    //stat the (stable) slot in the requested state: this fails for an entry deleted in the
651	    //current state (read with Current) or a newly added entry (read with Original)
652	    if (zip_stat_index(zipHandle, zipEntry.getIndex(), flag, &stat)!=0) { return ZipEntry(); }
653	
654	    ZipEntry resolved = createEntry(&stat);
655	    if (outSize!=nullptr) { *outSize = stat.size; }
656	    return resolved;
657	}
658	
659	vector<ZipEntry> ZipArchive::getEntries(State state) const {
660	    if (!isOpen()) { return vector<ZipEntry>(); }
661	
662	    struct zip_stat stat;
663	    zip_stat_init(&stat);
664	
665	    vector<ZipEntry> entries;
666	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
667	    libzippp_int64 nbEntries = getNbEntries(state);
668	    for(libzippp_int64 i=0 ; i<nbEntries ; ++i) {
669	        int result = zip_stat_index(zipHandle, i, flag, &stat);
670	        if (result==0) {
671	            ZipEntry entry = createEntry(&stat);
672	            entries.push_back(entry);
673	        } else {
674	            //TODO handle read error => crash ?
675	        }
676	    }
677	    return entries;
678	}
