680	bool ZipArchive::hasEntry(const string& name, bool excludeDirectories, bool caseSensitive, State state) const {
681	    if (!isOpen()) { return false; }
682	
683	    int flags = 0;
684	    if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
685	    if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
686	    if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
687	    else { flags = flags | ZIP_FL_ENC_GUESS; }
688	
689	    libzippp_int64 index = zip_name_locate(zipHandle, name.c_str(), flags);
690	    return index>=0;
