693	ZipEntry ZipArchive::getEntry(const string& name, bool excludeDirectories, bool caseSensitive, State state) const {
694	    if (isOpen()) {
695	        int flags = 0;
696	        if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
697	        if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
698	        if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
699	        else { flags = flags | ZIP_FL_ENC_GUESS; }
700	
701	        libzippp_int64 index = zip_name_locate(zipHandle, name.c_str(), flags);
702	        if (index>=0) {
703	            //the located index must be stat'd in the SAME state: locating a renamed entry
704	            //in the original state gives the original slot, whose name and size are the
705	            //original ones (using the current stat here would return the new name/length)
706	            return getEntry(index, state);
707	        } else {
708	            //name not found in the requested state
709	        }
710	    }
711	    return ZipEntry();
712	}
