714	ZipEntry ZipArchive::getEntry(libzippp_int64 index, State state) const {
715	    if (isOpen()) {
716	        struct zip_stat stat;
717	        zip_stat_init(&stat);
718	        int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
719	        int result = zip_stat_index(zipHandle, index, flag, &stat);
720	        if (result==0) {
721	            return createEntry(&stat);
722	        } else {
723	            //index not found / invalid index
724	        }
725	    }
726	    return ZipEntry();
727	}
