750	
751	void* ZipArchive::readEntry(const ZipEntry& zipEntry, bool asText, State state, libzippp_uint64 size) const {
752	    if (!isOpen()) { return nullptr; }
753	    if (!isEntryUsable(zipEntry)) { return nullptr; }
754	
755	    //resolve the entry in the requested state: the uncompressed size and the existence of
756	    //the entry depend on the state (a replacement may be longer, shorter or empty, a deleted
757	    //entry is only readable as Original and a newly added one only as Current)
758	    libzippp_uint64 entrySize = 0;
759	    ZipEntry resolved = resolveEntry(zipEntry, state, &entrySize);
760	    if (resolved.isNull()) { return nullptr; }
761	
762	    int flag = stateFlags(state);
763	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
764	    if (zipFile) {
765	        //zero means "read the whole content" and a too big length returns all of it; the
766	        //captured zipEntry size is intentionally never used to bound the read
767	        libzippp_uint64 uisize = size==0 || size>entrySize ? entrySize : size;
768	
769	        char* data = NEW_CHAR_ARRAY(uisize+(asText ? 1 : 0))
770	        if (!data) { //allocation error
771	            zip_fclose(zipFile);
772	            return nullptr;
773	        }
774	
775	        libzippp_int64 result = zip_fread(zipFile, data, uisize);
776	        zip_fclose(zipFile);
777	
778	        //avoid buffer copy
779	        if (asText) { data[uisize] = '\0'; }
780	
781	        libzippp_int64 isize = (libzippp_int64)uisize;
782	        if (result==isize) {
783	            return data;
784	        } else { //unexpected number of bytes read => crash ?
785	            delete[] data;
786	        }
787	    } else {
788	        //unable to read the entry (e.g. it does not exist in the requested state) => crash ?
789	    }
790	
791	    return nullptr;
792	}
793	
794	void* ZipArchive::readEntry(const string& zipEntry, bool asText, State state, libzippp_uint64 size) const {
795	    //the name is interpreted in the requested state: there is no fallback to the other state
796	    //if the name does not exist in this one
797	    ZipEntry entry = getEntry(zipEntry, false, true, state);
798	    if (entry.isNull()) { return nullptr; }
799	    return readEntry(entry, asText, state, size);
800	}
801	
802	int ZipArchive::deleteEntry(const ZipEntry& entry) const {
803	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
804	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
805	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //deletion not allowed
806	
807	    if (entry.isFile()) {
808	        int result = zip_delete(zipHandle, entry.getIndex());
809	        if (result==0) { return 1; }
810	        return LIBZIPPP_ERROR_UNKNOWN; //unable to delete the entry
811	    } else {
812	        int counter = 0;
813	        vector<ZipEntry> allEntries = getEntries();
814	        vector<ZipEntry>::const_iterator eit;
815	        for(eit=allEntries.begin() ; eit!=allEntries.end() ; ++eit) {
816	            ZipEntry ze = *eit;
817	            string::size_type startPosition = ze.getName().find(entry.getName());
818	            if (startPosition==0) {
819	                int result = zip_delete(zipHandle, ze.getIndex());
820	                if (result==0) { ++counter; }
821	                else { return LIBZIPPP_ERROR_UNKNOWN; } //unable to remove the current entry
822	            }
823	        }
824	        return counter;
825	    }
826	}
