828	int ZipArchive::deleteEntry(const string& e) const {
829	    ZipEntry entry = getEntry(e);
830	    if (entry.isNull()) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
831	    return deleteEntry(entry);
832	}
833	
834	int ZipArchive::renameEntry(const ZipEntry& entry, const string& newNameIn) const {
835	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
836	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
837	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //renaming not allowed
838	    if (newNameIn.length()==0) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
839	
840	    bool isDir = entry.isDirectory();
841	    string newName = newNameIn;
842	    if (isDir) {
843	        //a '/' is automatically appended to the destination of a directory
844	        if (!LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { newName += LIBZIPPP_ENTRY_PATH_SEPARATOR; }
845	    } else {
846	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { return LIBZIPPP_ERROR_INVALID_PARAMETER; } //a file cannot be renamed as a directory
847	    }
848	
849	    string sourceName = entry.getName();
850	    if (newName==sourceName) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
851	
852	    /*
853	     * Enumerate ALL the entries of the CURRENT state of the archive (i.e. including any
854	     * uncommitted addition/deletion/replacement/rename). Slots freed by zip_delete are
855	     * reported with a null name by libzip and simply skipped.
856	     */
857	    struct RenameItem {
858	        zip_uint64_t index;
859	        string oldName;
860	        string targetName;
861	    };
862	    vector<RenameItem> movedItems;
863	    vector<string> externalNames;
864	
865	    zip_int64_t nbSlots = zip_get_num_entries(zipHandle, 0);
866	    for(zip_int64_t i=0 ; i<nbSlots ; ++i) {
867	        const char* currentName = zip_get_name(zipHandle, (zip_uint64_t)i, ZIP_FL_ENC_GUESS);
868	        if (currentName==nullptr) { continue; } //entry deleted in the current (uncommitted) state
869	
870	        string name(currentName);
871	        bool participates = false;
872	        string targetName;
873	        if (isDir) {
874	            if (name==sourceName) {
875	                participates = true;
876	                targetName = newName;
877	            } else if (name.compare(0, sourceName.length(), sourceName)==0) {
878	                participates = true; //descendant of the moved directory
879	                targetName = newName + name.substr(sourceName.length());
880	            }
881	        } else {
882	            participates = (name==sourceName);
883	            targetName = newName;
884	        }
885	
886	        if (participates) {
887	            movedItems.push_back(RenameItem{(zip_uint64_t)i, name, targetName});
888	        } else {
889	            externalNames.push_back(name);
890	        }
891	    }
892	
893	    //the source entry itself must be part of the current archive
894	    bool sourceFound = false;
895	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
896	        if (it->oldName==sourceName) { sourceFound = true; break; }
897	    }
898	    if (!sourceFound) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
899	
900	    /*
901	     * Detect conflicts against the CURRENT state only: any entry that does not participate
902	     * in the move must not occupy the destination itself nor lie below it. Entries whose
903	     * parent directories are only implicit (no explicit directory entry in the archive) are
904	     * listed here as well, so a file such as new/target/last.txt prevents src/ from being
905	     * moved to new/target/ even when no new/ or new/target/ directory entry exists.
906	     */
907	    for(vector<string>::const_iterator it=externalNames.begin() ; it!=externalNames.end() ; ++it) {
908	        const string& external = *it;
909	        if (isDir) {
910	            if (external==newName || external.compare(0, newName.length(), newName)==0) {
911	                return LIBZIPPP_ERROR_UNKNOWN; //destination already occupied by an external entry: no overwrite, no merge
912	            }
913	        } else {
914	            if (external==newName) {
915	                return LIBZIPPP_ERROR_UNKNOWN; //the destination file already exists
916	            }
917	        }
918	    }
919	
920	    /*
921	     * Compute the (explicit) parent directories that will be missing once the entries have
922	     * been moved. A directory that is itself moved never has to be re-created here (it keeps
923	     * existing as an entry, only its name changes), even when a moved entry's new parent
924	     * chain goes through it.
925	     */
926	    vector<string> parentsToCreate;
927	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
928	        //for a directory target (ending with '/'), the first parent to consider is above the
929	        //target directory itself, hence the search starts at the penultimate separator
930	        string::size_type searchPos = it->targetName.length()-1;
931	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(it->targetName) && searchPos>0) { searchPos -= 1; }
932	        string::size_type slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, searchPos);
933	        while(slash!=string::npos && slash>0) {
934	            string parent = it->targetName.substr(0, slash+1);
935	
936	            //a moved destination already exists as an entry after the move
937	            bool isMovedDestination = false;
938	            for(vector<RenameItem>::const_iterator mit=movedItems.begin() ; mit!=movedItems.end() ; ++mit) {
939	                if (mit->targetName==parent) { isMovedDestination = true; break; }
940	            }
941	            if (isMovedDestination) { break; } //all the ancestors above are shared with this moved directory
942	
943	            //an external entry already provides the directory (explicitly)
944	            bool isExternal = false;
945	            for(vector<string>::const_iterator eit=externalNames.begin() ; eit!=externalNames.end() ; ++eit) {
946	                if (*eit==parent) { isExternal = true; break; }
947	            }
948	            if (isExternal) { break; } //the prefix chain up to this directory already exists
949	
950	            bool alreadyScheduled = false;
951	            for(vector<string>::const_iterator pit=parentsToCreate.begin() ; pit!=parentsToCreate.end() ; ++pit) {
952	                if (*pit==parent) { alreadyScheduled = true; break; }
953	            }
954	            if (!alreadyScheduled) { parentsToCreate.push_back(parent); }
955	            slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, slash-1);
956	        }
957	    }
958	    //create the parents from the shallowest to the deepest
959	    std::sort(parentsToCreate.begin(), parentsToCreate.end());
960	
961	    /*
962	     * Apply the rename deepest-first. This ordering is what makes moving a directory below
963	     * its own path possible (e.g. a/ to a/b/): the descendants free the names the ancestors
964	     * are renamed to, and the freshly re-created parent directories are not touched.
965	     */
966	    std::sort(movedItems.begin(), movedItems.end(),
967	              [](const RenameItem& a, const RenameItem& b) { return a.targetName > b.targetName; });
968	
969	    vector<zip_uint64_t> renamedIndices;
970	    vector<string> renamedOldNames;
971	    bool failure = false;
972	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
973	        int result = zip_file_rename(zipHandle, it->index, it->targetName.c_str(), ZIP_FL_ENC_GUESS);
974	        if (result!=0) { failure = true; break; }
975	        renamedIndices.push_back(it->index);
976	        renamedOldNames.push_back(it->oldName);
977	    }
978	
979	    //create the missing parent directories (e.g. re-create a/ when a/ moved to a/b/)
980	    vector<zip_uint64_t> createdDirIndices;
981	    if (!failure) {
982	        for(vector<string>::const_iterator it=parentsToCreate.begin() ; it!=parentsToCreate.end() ; ++it) {
983	            zip_int64_t dirIndex = zip_dir_add(zipHandle, it->c_str(), ZIP_FL_ENC_GUESS);
984	            if (dirIndex<0) { failure = true; break; }
985	            createdDirIndices.push_back((zip_uint64_t)dirIndex);
986	        }
987	    }
988	
989	    if (failure) {
990	        /*
991	         * The move could not be completed: undo everything done during THIS call so that the
992	         * archive is restored to its exact pre-call state. The directories created during
993	         * the move are removed first (they may occupy the original names), then the renames
994	         * are replayed in the reverse order (shallowest-first). Any other pending change is
995	         * left untouched.
996	         */
997	        for(vector<zip_uint64_t>::reverse_iterator dit=createdDirIndices.rbegin() ; dit!=createdDirIndices.rend() ; ++dit) {
998	            zip_delete(zipHandle, *dit);
999	        }
1000	        for(zip_int64_t k=(zip_int64_t)renamedIndices.size()-1 ; k>=0 ; --k) {
1001	            zip_file_rename(zipHandle, renamedIndices[(size_t)k], renamedOldNames[(size_t)k].c_str(), ZIP_FL_ENC_GUESS);
1002	        }
1003	        return LIBZIPPP_ERROR_UNKNOWN;
1004	    }
1005	
1006	    return (int)movedItems.size();
1007	}
