1015	bool ZipArchive::addFile(const string& entryName, const string& file) const {
1016	    if (!isOpen()) { return false; }
1017	    if (mode==ReadOnly) { return false; } //adding not allowed
1018	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1019	
1020	    string::size_type lastSlash = entryName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1021	    if (lastSlash!=string::npos) { //creates the needed parent directories
1022	        string dirEntry = entryName.substr(0, lastSlash+1);
1023	        bool dadded = addEntry(dirEntry);
1024	        if (!dadded) { return false; }
1025	    }
1026	
1027	    const char* filepath = file.c_str();
1028	    zip_source* source = zip_source_file(zipHandle, filepath, 0, -1);
1029	    if (source!=nullptr) {
1030	        libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
1031	        if (result>=0) {
1032	            zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
1033	            if (useArchiveCompressionMethod) {
1034	              zip_set_file_compression(zipHandle, result, compressionMethod, 0);
1035	            }
1036	#ifdef LIBZIPPP_WITH_ENCRYPTION
1037	            if (isEncrypted()) {
1038	                if (zip_file_set_encryption(zipHandle,result,encryptionMethod,nullptr)!=0) { //unable to encrypt
1039	                    zip_source_free(source);
1040	                } else {
1041	                    return true;
1042	                }
1043	            } else {
1044	                return true;
1045	            }
1046	#else
1047	            return true;
1048	#endif
1049	        } else {
1050	            //unable to add the file
1051	            zip_source_free(source);
1052	        }
1053	    } else {
1054	        //unable to create the zip_source
1055	    }
1056	    return false;
1057	}
