1059	bool ZipArchive::addData(const string& entryName, const void* data, libzippp_uint64 length, bool freeData) const {
1060	    if (!isOpen()) { return false; }
1061	    if (mode==ReadOnly) { return false; } //adding not allowed
1062	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1063	
1064	    string::size_type lastSlash = entryName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1065	    if (lastSlash!=string::npos) { //creates the needed parent directories
1066	        string dirEntry = entryName.substr(0, lastSlash+1);
1067	        bool dadded = addEntry(dirEntry);
1068	        if (!dadded) { return false; }
1069	    }
1070	
1071	    zip_source* source = zip_source_buffer(zipHandle, data, length, freeData);
1072	    if (source!=nullptr) {
1073	        libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
1074	        if (result>=0) {
1075	            zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
1076	            if (useArchiveCompressionMethod) {
1077	              zip_set_file_compression(zipHandle, result, compressionMethod, 0);
1078	            }
1079	#ifdef LIBZIPPP_WITH_ENCRYPTION
1080	            if (isEncrypted()) {
1081	                if (zip_file_set_encryption(zipHandle,result,encryptionMethod,nullptr)!=0) { //unable to encrypt
1082	                    zip_source_free(source);
1083	                } else {
1084	                    return true;
1085	                }
1086	            } else {
1087	                return true;
1088	            }
1089	#else
1090	            return true;
1091	#endif
1092	        } else {
1093	            //unable to add the file
1094	            zip_source_free(source);
1095	        }
1096	    } else {
1097	        //unable to create the zip_source
1098	    }
