1106	bool ZipArchive::addEntry(const string& entryName) const {
1107	    if (!isOpen()) { return false; }
1108	    if (mode==ReadOnly) { return false; } //adding not allowed
1109	    if (!LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1110	
1111	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1112	    while (nextSlash!=string::npos) {
1113	        string pathToCreate = entryName.substr(0, nextSlash+1);
1114	        if (!hasEntry(pathToCreate)) {
1115	            libzippp_int64 result = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1116	            if (result==-1) { return false; }
1117	        }
1118	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1119	    }
