1144	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::ostream& ofOutput, State state, libzippp_uint64 chunksize) const {
1145	    if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1146	    std::function<bool(const void*,libzippp_uint64)> writeFunc = [&ofOutput](const void* data,libzippp_uint64 size){ ofOutput.write((char*)data, size); return bool(ofOutput); };
1147	    return readEntry(zipEntry, writeFunc, state, chunksize);
1148	}
1149	
1150	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::function<bool(const void*,libzippp_uint64)> writeFunc, State state, libzippp_uint64 chunksize) const {
1151	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1152	    //null entries, entries from other archives and entries from a previous opening are
1153	    //rejected before any data delivery (the output stream/callback is left untouched)
1154	    if (!isEntryUsable(zipEntry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1155	
1156	    //resolve the entry in the requested state: its existence and uncompressed size depend
1157	    //on the state. When it does not exist in the state, no data is delivered at all.
1158	    libzippp_uint64 maxSize = 0;
1159	    ZipEntry resolved = resolveEntry(zipEntry, state, &maxSize);
1160	    if (resolved.isNull()) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1161	
1162	    if (!chunksize) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; } // use the default chunk size (512K) if not specified by the user
1163	
1164	    int flag = stateFlags(state);
1165	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
1166	    if (!zipFile) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1167	
1168	    int iRes = LIBZIPPP_OK;
1169	
1170	    //an empty content succeeds without reading anything; a single zero-length delivery is
1171	    //still signalled to the output (this matches the historical behavior)
1172	    if (maxSize==0) {
1173	        if (!writeFunc("", 0)) {
1174	            zip_fclose(zipFile);
1175	            return LIBZIPPP_ERROR_OWRITE_FAILURE;
1176	        }
1177	        zip_fclose(zipFile);
1178	        return LIBZIPPP_OK;
1179	    }
1180	
1181	    //only allocate what a single delivery may need (the whole content when it is smaller
1182	    //than the chunk size) instead of the chunk size in every case
1183	    libzippp_uint64 bufferSize = maxSize<chunksize ? maxSize : chunksize;
1184	    char* data = NEW_CHAR_ARRAY(bufferSize)
1185	    if (data!=nullptr) {
1186	        //stream the exact, state-resolved length in successive chunks: this delivers the
1187	        //whole content exactly once (chunksize bigger than, equal to, or not a divisor of
1188	        //the content length are all handled by the same loop)
1189	        libzippp_uint64 remaining = maxSize;
1190	        while (remaining>0) {
1191	            libzippp_uint64 toRead = remaining<bufferSize ? remaining : bufferSize;
1192	            libzippp_int64 result = zip_fread(zipFile, data, toRead);
1193	            if (result<0) {
1194	                iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
1195	                break;
1196	            }
1197	            if (static_cast<libzippp_uint64>(result)!=toRead) {
1198	                iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
1199	                break;
1200	            }
1201	            if (!writeFunc(data, toRead)) {
1202	                iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
1203	                break;
1204	            }
1205	            remaining -= toRead;
1206	        }
1207	        delete[] data;
1208	    } else {
1209	        iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
1210	    }
1211	    zip_fclose(zipFile);
1212	    return iRes;
1213	}
