51	// Adds an entry directly through libzip. Unlike ZipArchive::addData, this helper does not
52	// create the parent directories, so files can be inserted with only implicit parent
53	// directories (no explicit "dir/" entry in the archive). A name ending with '/' creates a
54	// directory entry.
55	static void addRawEntry(zip* zh, const string& name, const char* content) {
56	    if (!name.empty() && name[name.size()-1]=='/') {
57	        assert(zip_dir_add(zh, name.c_str(), 0) >= 0);
58	    } else {
59	        zip_source_t* source = zip_source_buffer(zh, content, strlen(content), 0);
60	        assert(source != nullptr);
61	        assert(zip_file_add(zh, name.c_str(), source, 0) >= 0);
62	    }
63	}
