    assert(!z1.hasEntry("victim.txt"));
    assert(z1.hasEntry("dir/moved.txt"));
    assert(!z1.hasEntry("dir/other.txt"));
    assert(z1.getComment() == "archive-comment");
    assert(z1.hasEntry("dir/")); //existing parent directory untouched

