    {
        ZipArchive z("test.zip");
        z.open(ZipArchive::Write);
        char* data = (char*)malloc(4);
        memcpy(data, "DIS", 4);
        assert(z.addData("gone.txt", data, 3, true));
        z.discard();
        assert(!z.isOpen());
    }

