        r.open(ZipArchive::ReadOnly);
        assert(r.getEntry("kept.txt").readAsText() == "KEPT");
        assert(!r.hasEntry("bad.txt"));
        r.close();
        r.unlink();
    }

    cout << " done." << endl;
}

